#!/usr/bin/env python3
"""Build board-spec-v3.json from keyframes/v3/picks and push with cutroom/board_builder.py"""
import json,os,subprocess
D=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
P=os.path.join(D,'keyframes/v3/picks/')
F=os.path.join(D,'reference/frames/frame_%04d.jpg')
spec=json.load(open(os.path.join(D,'board-spec.json')))  # reuse reference lane, notes, moodboard
W={1:('W1 WEEKENDER','Margaret, early 60s',"Honestly, my whole weekend is in this bag right now.","This is the Weekender from Velantra. It's a Birkin-inspired shape that they scaled up into a travel bag, and there's no logo on it anywhere.","And the rest?","Jacket's Veronica Beard, trousers are Frame, and the hat has no label.","Show us the arm","The cuff is David Yurman and the watch is a Rolex.","It holds three days' worth of clothes and it still fits in the overhead bin, which is all I need.","18 x 14.5 x 7 in: as wide as her shoulders, hip to just above the knee"),
   2:('W2 MERIDIAN','Diane, late 50s',"Honestly, everyone's been stopping me about this bag all day.","This is the Meridian from Velantra. It's all pebbled leather with silver hardware, there's no logo on it anywhere, and my laptop actually sits flat inside it.","And the rest?","The dress is Zimmermann, the hat is Janessa Leone, and the shoes are Aquazzura.","Show us the rings","The rings are David Yurman, and this little one was my grandmother's.","Everyone assumes I paid way more for it than I did, which I kind of love.","14.6 x 9.4 x 5.9 in (37 x 24 x 15 cm): as wide as her forearm, a little taller than her hand"),
   3:('W3 VIVIENNE','Celeste, mid 40s',"Okay, I'm going to start with the bag because it's brand new.","This is the Vivienne from Velantra. It's that Birkin-inspired shape but it's soft, it's vegetable-tanned leather, and there's no logo on it anywhere.","And the rest?","The coat is Max Mara, the trousers are Vince, and the boots are Manolo.","And the watch?","It's a Cartier, it was a gift from my husband.","It's on pre-order and ships in October, and they've got the whole collection on sale right now, link's below.","38 x 27 x 20 cm (about 15 x 10.5 x 8 in): as wide as her forearm, one and a half hand lengths tall")}
files={1:('W1-WEEKENDER-K1-full.png','W1-WEEKENDER-K2-lift-full.png','W1-WEEKENDER-K3-arm-full.png'),2:('W2-MERIDIAN-K1-full.png','W2-MERIDIAN-K2-lift-full.png','W2-MERIDIAN-K3-rings-full.png'),3:('W3-VIVIENNE-K1-full.png','W3-VIVIENNE-K2-lift-full.png','W3-VIVIENNE-K3-watch-full.png')}
def t(a,b): return f"{a//60}:{a%60:02d}-{b//60}:{b%60:02d}"
beats=[]
for n in (1,2,3):
    o=30*(n-1); name,who,hook,intro,card2,rundown,card3,jew,close,scale=W[n]; k1,k2,k3=files[n]
    beats+=[
     {"t":t(o,o+4),"script":f'CARD: What are you wearing today? / {name}: "{hook}"',"frame":P+k1,"visual":f"FULL BODY head to feet, {who}, bag at her side. {scale}.","emotion":"HOOK with the claim inside it. Card top of frame 0-3.5s.","note":"Seedance first frame. Whole body in frame; nobody else's hands or phone."},
     {"t":t(o+4,o+14),"script":f'"{intro}"',"frame":P+k2,"visual":"FULL BODY; she lifts the bag in front of her at waist height, front square to lens. CAMERA tilts DOWN to the bag while she talks, holds, tilts back UP to full body on the last words.","emotion":"PRODUCT INTRO by 0:06 + attribute stack. The tilt is the review.","note":f"Bag at true size ({scale}). Hardware sharp. Hands rest on the handles, never press the closure."},
     {"t":t(o+14,o+19),"script":f'CARD: {card2} / "{rundown}"',"frame":P+k1,"visual":"FULL BODY; she flicks two fingers at each piece as she names it; small tilt down to the shoes and back.","emotion":"RUNDOWN. The line follows the gesture.","note":"Say what she points at."},
     {"t":t(o+19,o+23),"script":f'CARD: {card3} / "{jew}"',"frame":P+k3,"visual":"FULL BODY; she raises the wrist / hand toward the lens; camera tilts to it and back. The named jewelry is ON her and reads correctly, watch dial upright.","emotion":"JEWELRY BEAT with the product still hanging from her arm.","note":"Cuff + Rolex / cable rings + distinct heirloom ring / Cartier tank."},
     {"t":t(o+23,o+30),"script":f'"{close}"',"frame":P+k1,"visual":"FULL BODY, she looks at the interviewer and smiles, bag at her side.","emotion":"CLOSE. Complete sentence, no price, no fragments.","note":"Hard cut to the next woman." if n<3 else "Then the 3s end card: Every bag in this video is on sale right now. Link below."},
    ]
spec['timelines'][1]={"label":"OUR VERSION v3: full body every shot, true bag sizes, props match the words","source":"Velantra, 3 x 30s + 3s end card = 93s, runs to the collection page","beats":beats}
spec['summary']="v3 (2026-09-03) RESTORYBOARD after Brooks's review. Whole body in every shot, camera tilts down to the bag during the review and back up. Bags at true dimensions anchored to her body. Every named prop on screen and correct (cuff + Rolex upright, David Yurman cable rings + a distinct heirloom ring, Cartier tank upright, plain tote interior with no label, Vivienne straps hanging beside the side edges). Script fixes: 'no label', 'the rings are David Yurman', 'the trousers are Vince'. Pronunciation reference and QA now cover every proper noun. KEYFRAMES ON THE BOARD FOR APPROVAL; Seedance fires after."
spec['notes'].insert(0,{"title":"v3 RULINGS (Brooks 9/03)","text":"Whole body in all shots, tilt down to the bag for the review. True dims: Weekender 18x14.5x7 in, Meridian 14.6x9.4x5.9 in (37x24x15 cm), Vivienne 38x27x20 cm. Props must match the words (cuff shown, DY cable rings, heirloom ring distinct, watches upright). No invented interior label. Fix 'Beard', 'Leone', 'Aquazzura' pronunciation. 'No label' not 'no brand'. 'Trousers are Vince'.","color":"#fdf3c9"})
json.dump(spec,open(os.path.join(D,'board-spec-v3.json'),'w'),indent=1)
print(subprocess.run(['python3','/Users/brooksorradre2/Documents/marketing brain/cutroom/board_builder.py',os.path.join(D,'board-spec-v3.json')],capture_output=True,text=True).stdout[-200:])
